// Block (composition) — responsive numbered steps for explaining a process.
// Card and Badge own their look; Grid and Stack own arrangement.
import type { ReactNode, Ref } from "react";
import { Badge } from "../components/Badge";
import { Card } from "../components/Card";
import { Grid } from "../layouts/Grid";
import type { Responsive } from "../layouts/responsive";
import { Stack } from "../layouts/Stack";
import "./StepsHowItWorks.css";

export interface StepsHowItWorksProps {
  steps: {
    title: string;
    description: string;
    icon?: ReactNode;
  }[];
  columns?: Responsive<number>;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function StepsHowItWorks({
  steps,
  columns = { small: 1, medium: 3 },
  className,
  ref,
}: StepsHowItWorksProps) {
  return (
    <Grid
      as="section"
      ref={ref}
      aria-label="How it works"
      columns={columns}
      gap="medium"
      className={className ? `sd-stepshowitworks ${className}` : "sd-stepshowitworks"}
    >
      {steps.map((step, index) => (
        <Card key={`${step.title}-${index}`}>
          <Stack gap="small" className="sd-stepshowitworks__content">
            {step.icon ?? <Badge className="sd-stepshowitworks__number">{index + 1}</Badge>}
            {/* spacing: attachment — the glyph heads the title under it.
              The name and its supporting line are ONE unit, so they group at `x-small` while the
              section around them sits at least a rung looser — otherwise the same gap
              separates the pair as separates it from everything else. */}
            <>
              <Stack gap="x-small" className="sd-stepshowitworks__heading">
                <h3 className="sd-stepshowitworks__title sd-type-title-medium">{step.title}</h3>
                <p className="sd-stepshowitworks__description sd-type-body-medium">
                  {step.description}
                </p>
              </Stack>
            </>
          </Stack>
        </Card>
      ))}
    </Grid>
  );
}

/* StepsHowItWorks.css — .sd-stepshowitworks (Block)
   Arrangement only: fills its section and resets native text margins. */
.sd-stepshowitworks {
  width: 100%;
}

.sd-stepshowitworks__title,
.sd-stepshowitworks__description {
  margin: 0;
}

.sd-stepshowitworks__description {
  color: var(--sd-color-text-muted);
}

/* A Badge is a chip: content-sized. The Stack around it is a column and a Stack's `align` defaults
   to stretch, which pulled the step number to the card's full width. Same statement as
   `.sd-agendalist__time`, which is the other Block that puts a chip in a column. */
.sd-stepshowitworks__number {
  align-self: start;
}
